            var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(8)};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,385));Controls.Add(layout);canvas=new IntentCanvas(this){Name="serviceWaypointCanvas",Dock=DockStyle.Fill};layout.Controls.Add(canvas,0,0);
