            add(new Label{Text="Inspect one service-destination and waypoint callback on a separate copied map. It changes queued intent; the fleet does not travel. Yard positions, starting queue and skip conditions are supplied diagnostic inputs. No world clock runs."},94);
            add(new Label{Text="Pending preset (apply with Load)"},20);profile.Name="serviceWaypointProfile";profile.DropDownStyle=ComboBoxStyle.DropDownList;profile.DropDownWidth=480;foreach(string p in PracticeServiceWaypointStudyBasis.Presets)profile.Items.Add(p);profile.SelectedIndex=0;add(profile,30);
