        protected override void OnKeyDown(KeyEventArgs e)
        {
            if(IsDisposed||Disposing){e.Handled=e.SuppressKeyPress=true;return;}if(e.KeyCode==Keys.Escape||e.KeyCode==Keys.Enter||e.KeyCode==Keys.Space){var button=ActiveControl as Button;if(e.KeyCode==Keys.Escape||button!=null){e.Handled=e.SuppressKeyPress=true;if(held.Add(e.KeyCode)){if(e.KeyCode==Keys.Escape)Close();else if(button.Enabled)button.PerformClick();}return;}}base.OnKeyDown(e);
        }
        void Feedback(string text){if(IsDisposed||Disposing)return;feedback.ForeColor=Color.LightSteelBlue;feedback.Text=text;}
        void Reject(string text){if(IsDisposed||Disposing)return;feedback.ForeColor=Color.Orange;feedback.Text="Rejected; applied copy preserved. "+text;Sync();}
        void LoadCopy(){if(basis==null){Reject("No supported copied map basis.");return;}state=basis.CreateFixture(profile.SelectedIndex);Feedback("Copied origin, candidate yards and supplied queue loaded. Apply one callback to compare.");Sync();}
        static string QueueText(byte[] f,int n){int x=BitConverter.ToInt16(f,16*492+40+n*2),y=BitConverter.ToInt16(f,16*492+50+n*2);return x==-1?"end; Y="+y:x+","+y;}
        void Sync()
        {
            if(IsDisposed||Disposing)return;load.Enabled=basis!=null;apply.Enabled=state!=null&&!state.Executed;reset.Enabled=state!=null;if(state==null){summary.Text="No admitted copied state.";return;}
            var before=state.CopyBeforeFleetPool();var after=state.CopyFleetPool();var bt=state.BeforeBacking.CopyTaskRecord(16);var at=state.Backing.CopyTaskRecord(16);var result=state.Result;
            string destination=result==null?"not visited":result.Destination==null?"not visited (skip)":result.Destination.SelectedYard<0?"no eligible yard; cached destination held":"yard "+result.Destination.SelectedYard;
            summary.Text="Applied: "+PracticeServiceWaypointStudyBasis.Presets[state.Preset]+"\r\nFleet 16 · copied callback "+(state.Executed?"complete":"prepared")+"\r\nOutcome: "+(result==null?"not applied":result.Outcome.ToString())+"\r\nDestination: "+destination+"\r\nGoal field "+BitConverter.ToInt32(bt,200)+" → "+BitConverter.ToInt32(at,200)+"\r\nReference field "+BitConverter.ToInt32(bt,308)+" → "+BitConverter.ToInt32(at,308)+"\r\nReplaced point: "+(result==null||result.ReplacedWaypoint<0?"none":(result.ReplacedWaypoint+1).ToString())+"; origin fixed.";
            queue.Items.Clear();for(int n=0;n<5;n++)queue.Items.Add((n+1)+": "+QueueText(before,n)+" → "+QueueText(after,n)+(result!=null&&result.ReplacedWaypoint==n?"  [replaced]":""));
            details.Text="Supplied fleet 16 origin: "+state.OriginX+","+state.OriginY+" (unchanged).\r\nStarting goal 4 and cached destination 550,290 are readable study inputs. Native comparisons also use wider diagnostic tags. Only one callback runs; Reset restores the applied copy.\r\n\r\nRecovered task 11 caller: no first waypoint, active navigation field, or source mode 2 returns before destination selection. An inactive nonnegative reference is cleared; negative values are retained. Strict nearest-yard comparison keeps the earlier eligible yard on ties. Goal becomes 2 only after selection is invoked. The point before the FIRST queue gap is overwritten, not appended. Later queue words remain opaque.\r\n\r\nNo eligible yard preserves cached DWORD coordinates. WORD output can wrap without clamping; the signed-limit preset demonstrates that boundary. The plot auto-fits supplied coordinates and is a modern diagram, not source map rendering. Gray points beyond a gap are unused queue data.\r\n\r\nSource UI requests: 0; no time, RNG, travel, admission, repair, cinematics or full AI world runs.\r\n\r\nRead-only fields: task kind "+BitConverter.ToInt32(at,0)+"; navigation flag "+BitConverter.ToInt32(at,304)+"; fleet mode "+BitConverter.ToInt32(after,16*492+476)+"; raw status 485 "+before[16*492+485]+" → "+after[16*492+485]+". Raw field meanings beyond the compared branches remain unresolved. Closing preserves your battle and settings.";
            canvas.Invalidate();
        }
        sealed class IntentCanvas : Control
        {
            readonly PracticeServiceWaypointStudy owner;
            internal IntentCanvas(PracticeServiceWaypointStudy owner){this.owner=owner;DoubleBuffered=true;ResizeRedraw=true;BackColor=owner.BackColor;}
            protected override void OnPaint(PaintEventArgs e)
