                base.OnPaint(e);var state=owner.state;if(state==null)return;var before=state.CopyBeforeFleetPool();var after=state.CopyFleetPool();var points=new List<PointF>{new PointF(0,0),new PointF(640,640),new PointF(state.OriginX,state.OriginY)};
                foreach(var f in new[]{before,after}){for(int n=0;n<5;n++){int x=BitConverter.ToInt16(f,16*492+40+n*2);if(x!=-1)points.Add(new PointF(x,BitConverter.ToInt16(f,16*492+50+n*2)));}foreach(int yard in new[]{2,3})if(BitConverter.ToInt32(f,yard*492)==2)points.Add(new PointF(BitConverter.ToInt16(f,yard*492+12),BitConverter.ToInt16(f,yard*492+14)));}
                double minX=0,minY=0,maxX=640,maxY=640;foreach(var p in points){minX=Math.Min(minX,p.X);minY=Math.Min(minY,p.Y);maxX=Math.Max(maxX,p.X);maxY=Math.Max(maxY,p.Y);}double scale=Math.Min(Math.Max(1,ClientSize.Width-110)/(maxX-minX),Math.Max(1,ClientSize.Height-190)/(maxY-minY));
                Func<float,float,PointF> screen=delegate(float x,float y){return new PointF(55+(float)((x-minX)*scale),100+(float)((y-minY)*scale));};e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;e.Graphics.DrawString("Copied positions and queued intent · +Y downward",owner.Font,Brushes.WhiteSmoke,12,12);e.Graphics.DrawString("Gold origin · green yard · gray before · cyan after",owner.Font,Brushes.LightSteelBlue,12,36);
                using(var pen=new Pen(Color.FromArgb(34,59,76))){for(int n=0;n<=640;n+=80){e.Graphics.DrawLine(pen,screen(n,0),screen(n,640));e.Graphics.DrawLine(pen,screen(0,n),screen(640,n));}}var zero=screen(0,0);using(var pen=new Pen(Color.SlateGray))e.Graphics.DrawRectangle(pen,zero.X,zero.Y,(float)(640*scale),(float)(640*scale));
                DrawQueue(e.Graphics,before,screen,Color.SlateGray,true);if(state.Executed&&state.Result.SelectorInvoked)DrawQueue(e.Graphics,after,screen,Color.Cyan,false);
                int chosen=state.Executed&&state.Result.Destination!=null?state.Result.Destination.SelectedYard:-1;foreach(int yard in new[]{2,3}){if(BitConverter.ToInt32(after,yard*492)!=2)continue;var p=screen(BitConverter.ToInt16(after,yard*492+12),BitConverter.ToInt16(after,yard*492+14));using(var brush=new SolidBrush(yard==chosen?Color.LightGreen:Color.SteelBlue))e.Graphics.FillRectangle(brush,p.X-6,p.Y-6,12,12);e.Graphics.DrawString("Yard "+yard,owner.Font,yard==chosen?Brushes.LightGreen:Brushes.LightSteelBlue,p.X+8,p.Y-26);}
                var origin=screen(state.OriginX,state.OriginY);e.Graphics.FillEllipse(Brushes.Gold,origin.X-6,origin.Y-6,12,12);e.Graphics.DrawString("Fleet 16",owner.Font,Brushes.Gold,origin.X-38,origin.Y+10);
                e.Graphics.DrawString("Origins fixed; lines show intent, not a computed route.\r\nView auto-fits supplied coordinates. No world clock or movement.",owner.Font,Brushes.LightSteelBlue,new RectangleF(12,ClientSize.Height-66,Math.Max(1,ClientSize.Width-24),62));
            }
            void DrawQueue(Graphics g,byte[] f,Func<float,float,PointF> screen,Color color,bool old)
            {
                int last=-1;for(int n=0;n<5;n++){if(BitConverter.ToInt16(f,16*492+40+n*2)==-1)break;last=n;}bool gap=false;var previous=screen(owner.state.OriginX,owner.state.OriginY);using(var pen=new Pen(color,old?1.5f:2.2f)){if(old)pen.DashStyle=DashStyle.Dash;for(int n=0;n<5;n++){int x=BitConverter.ToInt16(f,16*492+40+n*2);if(x==-1){gap=true;continue;}var p=screen(x,BitConverter.ToInt16(f,16*492+50+n*2));if(!gap){g.DrawLine(pen,previous,p);previous=p;}g.DrawEllipse(pen,p.X-4,p.Y-4,8,8);if(!gap&&n==last)using(var brush=new SolidBrush(color))g.DrawString("Q"+(n+1)+(old?(owner.state.Executed?" before":" last"):" replaced"),owner.Font,brush,p.X+7,p.Y+5);}}
